order by rows desc nulls last limit 40"""
p=subprocess.run(['curl','-s','--max-time','50','-X','POST','-H',f'Authorization: Bearer {T}','-H','Content-Type: application/json','--data-binary','@-','https://api.supabase.com/v1/projects/kvclcdjmjghndxsngfzb/database/query'],input=json.dumps({'query':q}),capture_output=True,text=True)
try:
    for r in json.loads(p.stdout): print(f"{r['table_name']:38} rows={r['rows']}")
except Exception: print('ERR', p.stdout[:300])
EOF

